script.setup:
// d3-delaunay triangulates moving points every frame; WebGL draws the triangles.
const { Delaunay } = await ctx.utils.import("https://esm.sh/d3-delaunay@6.0.4");
ctx.state.Delaunay = Delaunay;
const seeds = [];
for (let i = 0; i < 360; i++) seeds.push({ x: Math.random(), y: Math.random(), phase: Math.random() * 6.283, amp: 0.01 + Math.random() * 0.03 });
// Fixed points along the border keep the mesh covering the whole canvas.
for (let i = 0; i <= 10; i++) {
  const t = i / 10;
  seeds.push({ x: t, y: 0, fixed: true }, { x: t, y: 1, fixed: true }, { x: 0, y: t, fixed: true }, { x: 1, y: t, fixed: true });
}
ctx.state.seeds = seeds;
ctx.state.coords = new Float64Array(seeds.length * 2);
const gl = ctx.gl;
ctx.state.vao = gl.createVertexArray();
ctx.state.buffer = gl.createBuffer();
gl.bindVertexArray(ctx.state.vao);
gl.bindBuffer(gl.ARRAY_BUFFER, ctx.state.buffer);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 20, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 3, gl.FLOAT, false, 20, 8);
gl.bindVertexArray(null);
ctx.state.p = ctx.utils.createProgram('#version 300 es\nlayout(location=0) in vec2 a_position; layout(location=1) in vec3 a_color;\nout vec3 v_color;\nvoid main(){ v_color = a_color; gl_Position = vec4(a_position * 2.0 - 1.0, 0.0, 1.0); }', '#version 300 es\nprecision highp float; in vec3 v_color; out vec4 outColor;\nvoid main(){ outColor = vec4(v_color, 1.0); }');

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
const t = ctx.time * u.u_speed;
const [mx, my] = ctx.mouse;
s.seeds.forEach((p, i) => {
  let x = p.x, y = p.y;
  if (!p.fixed) {
    x += Math.sin(t + p.phase) * p.amp;
    y += Math.cos(t * 0.8 + p.phase * 1.3) * p.amp;
    // Points shy away from the pointer.
    const dx = x - mx, dy = y - (1 - my), d2 = dx * dx + dy * dy;
    const push = 0.012 / (d2 + 0.004);
    x += dx * push * 0.05; y += dy * push * 0.05;
  }
  s.coords[i * 2] = x; s.coords[i * 2 + 1] = y;
});
const tri = new s.Delaunay(s.coords).triangles;
const a = u.u_colorA, b = u.u_colorB;
const data = new Float32Array(tri.length * 5);
for (let i = 0; i < tri.length; i += 3) {
  const p0 = tri[i] * 2, p1 = tri[i + 1] * 2, p2 = tri[i + 2] * 2;
  const cx = (s.coords[p0] + s.coords[p1] + s.coords[p2]) / 3, cy = (s.coords[p0 + 1] + s.coords[p1 + 1] + s.coords[p2 + 1]) / 3;
  // Facet shading: a fake normal from the triangle's winding area and position.
  const shade = 0.75 + 0.25 * Math.sin(cx * 9 + cy * 7 + t * 0.7);
  const k = Math.min(1, Math.max(0, cy + 0.15 * Math.sin(cx * 6 + t)));
  const r = (a[0] * (1 - k) + b[0] * k) * shade, g = (a[1] * (1 - k) + b[1] * k) * shade, bl = (a[2] * (1 - k) + b[2] * k) * shade;
  for (const p of [p0, p1, p2]) data.set([s.coords[p], s.coords[p + 1], r, g, bl], ((i + (p === p0 ? 0 : p === p1 ? 1 : 2)) * 5));
}
gl.clearColor(0, 0, 0, 1); gl.clear(gl.COLOR_BUFFER_BIT);
gl.useProgram(s.p);
gl.bindVertexArray(s.vao);
gl.bindBuffer(gl.ARRAY_BUFFER, s.buffer);
gl.bufferData(gl.ARRAY_BUFFER, data, gl.DYNAMIC_DRAW);
gl.drawArrays(gl.TRIANGLES, 0, tri.length);
gl.bindVertexArray(null);
ctx.publish("triangles", tri.length / 3);
